<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\OAuth\User\Domain\PublicLoginAuthResponse;
use Civi\Lughauth\Features\OAuth\User\Domain\RecoveryNotificationData;
use Civi\Lughauth\Features\OAuth\User\Domain\RegistrationNotificationData;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationResult;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;

final class UserDomainUnitTest extends TestCase
{
    // --- PublicLoginAuthResponse ---

    public function test_public_login_auth_response_stores_fields(): void
    {
        $auth = new AuthenticationResult(valid: true, id: 'user-1', tenant: 'tenant');
        $sessExp = new DateInterval('P1D');

        $resp = new PublicLoginAuthResponse(
            tenant: 'tenant',
            auth: $auth,
            issuer: 'https://auth.example.com/openid/tenant',
            clientId: 'my-client',
            sessionId: 'sess-123',
            sessionExpiration: $sessExp,
        );

        $this->assertSame('tenant', $resp->tenant);
        $this->assertSame($auth, $resp->auth);
        $this->assertSame('https://auth.example.com/openid/tenant', $resp->issuer);
        $this->assertSame('my-client', $resp->clientId);
        $this->assertSame('sess-123', $resp->sessionId);
    }

    // --- RecoveryNotificationData ---

    public function test_recovery_notification_data_stores_fields(): void
    {
        $tenant = new TenantRef('tenant-uid');
        $expires = new DateTimeImmutable('2026-06-01T10:00:00+00:00');

        $data = new RecoveryNotificationData(
            email: 'alice@example.com',
            name: 'Alice',
            tenant: $tenant,
            recoveryUrl: 'https://auth/recover?token=abc',
            expiresAt: $expires,
        );

        $this->assertSame('alice@example.com', $data->email);
        $this->assertSame('Alice', $data->name);
        $this->assertSame($tenant, $data->tenant);
        $this->assertSame('https://auth/recover?token=abc', $data->recoveryUrl);
        $this->assertSame($expires, $data->expiresAt);
    }

    // --- RegistrationNotificationData ---

    public function test_registration_notification_data_stores_fields(): void
    {
        $tenant = new TenantRef('tenant-uid');

        $data = new RegistrationNotificationData(
            email: 'bob@example.com',
            name: 'Bob',
            tenant: $tenant,
            activateUrl: 'https://auth/activate?token=xyz',
        );

        $this->assertSame('bob@example.com', $data->email);
        $this->assertSame('Bob', $data->name);
        $this->assertSame($tenant, $data->tenant);
        $this->assertSame('https://auth/activate?token=xyz', $data->activateUrl);
    }
}
